        "dob": { "type": "string", "format": "date" },
        "race": { "type": "string", "enum": ["WHITE", "BLACK", "HISPANIC", "ASIAN", "OTHER", "UNKNOWN"] },
        "sex": { "type": "string", "enum": ["M", "F", "X"] }
      }
    },
    "contact_info": {
      "type": "object",
      "properties": {
        "address": { "type": "string" },
        "phone": { "type": "string" },
        "email": { "type": "string", "format": "email" }
      }
    },
    "risk_score": { "type": "integer", "minimum": 0, "maximum": 10, "description": "Pretrial risk assessment score" }
